// Mineral staining is continuous over the assembled surface. The inherited vertex
// colors still distinguish matrix, fossil and restorations on each modeled bone.
function collectionFossilFinish(group){
  const materials=new Map();group.traverse(obj=>{
    const base=obj.material;if(!obj.isMesh||!base?.isMeshStandardMaterial||!obj.geometry.attributes.color)return;
    if(!materials.has(base)){
      const mat=base.clone();mat.roughness=.77;mat.metalness=.028;
      const previous=base.onBeforeCompile;
      mat.onBeforeCompile=(shader,renderer)=>{
        if(previous)previous.call(mat,shader,renderer);
        shader.vertexShader='varying vec3 osteoWorld;\n'+shader.vertexShader;
        shader.vertexShader=shader.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nosteoWorld=(modelMatrix*vec4(transformed,1.)).xyz;');
        shader.fragmentShader=`varying vec3 osteoWorld;
          float foHash(vec3 p){p=fract(p*.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}
          float foNoise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
            return mix(mix(mix(foHash(i),foHash(i+vec3(1,0,0)),f.x),mix(foHash(i+vec3(0,1,0)),foHash(i+vec3(1,1,0)),f.x),f.y),
                       mix(mix(foHash(i+vec3(0,0,1)),foHash(i+vec3(1,0,1)),f.x),mix(foHash(i+vec3(0,1,1)),foHash(i+vec3(1)),f.x),f.y),f.z);}
        `+shader.fragmentShader;
        shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>
          vec3 osteoFp=osteoWorld;float osteoFerric=foNoise(osteoFp*4.6),osteoGrain=foNoise(osteoFp*16.9),osteoPore=foNoise(osteoFp*53.);
          float osteoDark=clamp((.58-osteoFerric)*1.34+(.50-osteoGrain)*.62,0.,.67);
          diffuseColor.rgb*=mix(vec3(1.22,1.13,1.03),vec3(.47,.43,.42),osteoDark+.15*osteoGrain);
          diffuseColor.rgb*=.88+.21*osteoPore+.11*smoothstep(.6,.88,osteoGrain);`);
        shader.fragmentShader=shader.fragmentShader.replace('#include <normal_fragment_maps>',`#include <normal_fragment_maps>
          vec3 osteoDq0=dFdx(-vViewPosition),osteoDq1=dFdy(-vViewPosition),osteoR0=cross(osteoDq1,normal),osteoR1=cross(normal,osteoDq0);float osteoDet=dot(osteoDq0,osteoR0);
          vec3 osteoGrainGrad=dFdx(osteoPore)*osteoR0+dFdy(osteoPore)*osteoR1;normal=normalize(normal-.0025*sign(osteoDet)*osteoGrainGrad/max(abs(osteoDet),.000025));`);
      };mat.customProgramCacheKey=()=> 'amnh-fossil-mineral';materials.set(base,mat);
    }obj.material=materials.get(base);
  });
}

